      "id": "html-surfaces",
      "module": "./content/styles/html-elements.md.surfaces.ts",
      "source": "const surfaceNames = [\"surface\", \"surface-2\", \"surface-3\"];\nconst content = e(\"div\", { ui: [\"elg\", \"d-flex\", \"flex-col\", \"gap-2\"] }, ...surfaceNames.map((surface, index) => e(\"div\", {\n    ui: [\"elg\", surface, \"box\", \"p-3\"]\n}, surface + \" layer\", e(\"p\", { ui: [\"elg\", \"text-muted\", \"m-0\"] }, \"Content on \" + (index === 0 ? \"the page\" : \"a raised layer\") + \".\"))));\ndocument.body.append(content);",
      "code": "const surfaceNames = [\"surface\", \"surface-2\", \"surface-3\"];\nconst content = e(\"div\", { ui: [\"elg\", \"d-flex\", \"flex-col\", \"gap-2\"] }, ...surfaceNames.map((surface, index) => e(\"div\", {\n    ui: [\"elg\", surface, \"box\", \"p-3\"]\n}, surface + \" layer\", e(\"p\", { ui: [\"elg\", \"text-muted\", \"m-0\"] }, \"Content on \" + (index === 0 ? \"the page\" : \"a raised layer\") + \".\"))));\ndocument.body.append(content);",
      "sourceHtml": "<pre class=\"shiki shiki-themes github-light github-dark\" style=\"background-color:#fff;--shiki-dark-bg:#24292e;color:#24292e;--shiki-dark:#e1e4e8\" tabindex=\"0\"><code><span class=\"line\"><span style=\"color:#D73A49;--shiki-dark:#F97583\">const</span><span style=\"color:#005CC5;--shiki-dark:#79B8FF\"> surfaceNames</span><span style=\"color:#D73A49;--shiki-dark:#F97583\"> =</span><span style=\"color:#24292E;--shiki-dark:#E1E4E8\"> [</span><span style=\"color:#032F62;--shiki-dark:#9ECBFF\">\"surface\"</span><span style=\"color:#24292E;--shiki-dark:#E1E4E8\">, </span><span style=\"color:#032F62;--shiki-dark:#9ECBFF\">\"surface-2\"</span><span style=\"color:#24292E;--shiki-dark:#E1E4E8\">, </span><span style=\"color:#032F62;--shiki-dark:#9ECBFF\">\"surface-3\"</span><span style=\"color:#24292E;--shiki-dark:#E1E4E8\">];</span></span>\n<span class=\"line\"><span style=\"color:#D73A49;--shiki-dark:#F97583\">const</span><span style=\"color:#005CC5;--shiki-dark:#79B8FF\"> content</span><span style=\"color:#D73A49;--shiki-dark:#F97583\"> =</span><span style=\"color:#6F42C1;--shiki-dark:#B392F0\"> e</span><span style=\"color:#24292E;--shiki-dark:#E1E4E8\">(</span><span style=\"color:#032F62;--shiki-dark:#9ECBFF\">\"div\"</span><span style=\"color:#24292E;--shiki-dark:#E1E4E8\">, { ui: [</span><span style=\"color:#032F62;--shiki-dark:#9ECBFF\">\"elg\"</span><span style=\"color:#24292E;--shiki-dark:#E1E4E8\">, </span><span style=\"color:#032F62;--shiki-dark:#9ECBFF\">\"d-flex\"</span><span style=\"color:#24292E;--shiki-dark:#E1E4E8\">, </span><span style=\"color:#032F62;--shiki-dark:#9ECBFF\">\"flex-col\"</span><span style=\"color:#24292E;--shiki-dark:#E1E4E8\">, </span><span style=\"color:#032F62;--shiki-dark:#9ECBFF\">\"gap-2\"</span><span style=\"color:#24292E;--shiki-dark:#E1E4E8\">] }, </span><span style=\"color:#D73A49;--shiki-dark:#F97583\">...</span><span style=\"color:#24292E;--shiki-dark:#E1E4E8\">surfaceNames.</span><span style=\"color:#6F42C1;--shiki-dark:#B392F0\">map</span><span style=\"color:#24292E;--shiki-dark:#E1E4E8\">((</span><span style=\"color:#E36209;--shiki-dark:#FFAB70\">surface</span><span style=\"color:#24292E;--shiki-dark:#E1E4E8\">, </span><span style=\"color:#E36209;--shiki-dark:#FFAB70\">index</span><span style=\"color:#24292E;--shiki-dark:#E1E4E8\">) </span><span style=\"color:#D73A49;--shiki-dark:#F97583\">=></span><span style=\"color:#6F42C1;--shiki-dark:#B392F0\"> e</span><span style=\"color:#24292E;--shiki-dark:#E1E4E8\">(</span><span style=\"color:#032F62;--shiki-dark:#9ECBFF\">\"div\"</span><span style=\"color:#24292E;--shiki-dark:#E1E4E8\">, {</span></span>\n<span class=\"line\"><span style=\"color:#24292E;--shiki-dark:#E1E4E8\">    ui: [</span><span style=\"color:#032F62;--shiki-dark:#9ECBFF\">\"elg\"</span><span style=\"color:#24292E;--shiki-dark:#E1E4E8\">, surface, </span><span style=\"color:#032F62;--shiki-dark:#9ECBFF\">\"box\"</span><span style=\"color:#24292E;--shiki-dark:#E1E4E8\">, </span><span style=\"color:#032F62;--shiki-dark:#9ECBFF\">\"p-3\"</span><span style=\"color:#24292E;--shiki-dark:#E1E4E8\">]</span></span>\n<span class=\"line\"><span style=\"color:#24292E;--shiki-dark:#E1E4E8\">}, surface </span><span style=\"color:#D73A49;--shiki-dark:#F97583\">+</span><span style=\"color:#032F62;--shiki-dark:#9ECBFF\"> \" layer\"</span><span style=\"color:#24292E;--shiki-dark:#E1E4E8\">, </span><span style=\"color:#6F42C1;--shiki-dark:#B392F0\">e</span><span style=\"color:#24292E;--shiki-dark:#E1E4E8\">(</span><span style=\"color:#032F62;--shiki-dark:#9ECBFF\">\"p\"</span><span style=\"color:#24292E;--shiki-dark:#E1E4E8\">, { ui: [</span><span style=\"color:#032F62;--shiki-dark:#9ECBFF\">\"elg\"</span><span style=\"color:#24292E;--shiki-dark:#E1E4E8\">, </span><span style=\"color:#032F62;--shiki-dark:#9ECBFF\">\"text-muted\"</span><span style=\"color:#24292E;--shiki-dark:#E1E4E8\">, </span><span style=\"color:#032F62;--shiki-dark:#9ECBFF\">\"m-0\"</span><span style=\"color:#24292E;--shiki-dark:#E1E4E8\">] }, </span><span style=\"color:#032F62;--shiki-dark:#9ECBFF\">\"Content on \"</span><span style=\"color:#D73A49;--shiki-dark:#F97583\"> +</span><span style=\"color:#24292E;--shiki-dark:#E1E4E8\"> (index </span><span style=\"color:#D73A49;--shiki-dark:#F97583\">===</span><span style=\"color:#005CC5;--shiki-dark:#79B8FF\"> 0</span><span style=\"color:#D73A49;--shiki-dark:#F97583\"> ?</span><span style=\"color:#032F62;--shiki-dark:#9ECBFF\"> \"the page\"</span><span style=\"color:#D73A49;--shiki-dark:#F97583\"> :</span><span style=\"color:#032F62;--shiki-dark:#9ECBFF\"> \"a raised layer\"</span><span style=\"color:#24292E;--shiki-dark:#E1E4E8\">) </span><span style=\"color:#D73A49;--shiki-dark:#F97583\">+</span><span style=\"color:#032F62;--shiki-dark:#9ECBFF\"> \".\"</span><span style=\"color:#24292E;--shiki-dark:#E1E4E8\">))));</span></span>\n<span class=\"line\"><span style=\"color:#24292E;--shiki-dark:#E1E4E8\">document.body.</span><span style=\"color:#6F42C1;--shiki-dark:#B392F0\">append</span><span style=\"color:#24292E;--shiki-dark:#E1E4E8\">(content);</span></span></code></pre>",
